"""Run the payroll report. Do not edit this file."""

from payroll import process_payroll


def main():
    records = [
        {"name": "Floppsie", "hours": "40", "rate": "25"},
        {"name": "Felicity", "hours": "45", "rate": "20"},
        {"name": "Peter", "hours": "-5", "rate": "18"},
        {"name": "Goldhoarder", "hours": "50", "rate": "banana"},
        {"name": "Alice", "hours": "35", "rate": "30"},
        {"name": "Bob", "hours": "90", "rate": "15"},
        {"name": "Carol", "hours": "40"},
        {"name": "Dana", "hours": "42", "rate": "22.50"},
        {"name": "Eli", "hours": None, "rate": "20"},
        {"name": "", "hours": "30", "rate": "15"},
        {"name": "Grace", "hours": "20", "rate": "0"},
        {"hours": "40", "rate": "19"},
    ]
    report = process_payroll(records)
    print("PETER'S CATASTROPHIC PAYROLL SYSTEM")
    print("-" * 45)
    for result in report["results"]:
        if result["status"] == "PAID":
            print(f'{result["name"]}: PAID ${result["pay"]:.2f}')
        else:
            print(f'{result["name"]}: REJECTED — {result["error"]}')
    print("-" * 45)
    summary = report["summary"]
    print(f'Attempted:  {summary["attempted"]}')
    print(f'Successful: {summary["successful"]}')
    print(f'Rejected:   {summary["rejected"]}')
    print(f'Total pay:  ${report["total_pay"]:.2f}')


if __name__ == "__main__":
    main()
